dal,\n    NcTextField,\n    Pencil,\n    TrashCanOutline,\n  },\n  data() {\n    return {\n      loading: true,\n      saving: false,\n      saved: false,\n      error: '',\n      items: [],\n      query: '',\n      editingId: null,\n      showModal: false,\n      form: {\n        name: '',\n        description: '',\n        unitPrice: '',\n      },\n      fieldErrors: {},\n    }\n  },\n  computed: {\n    canSave() {\n      const cents = centsFromInput(this.form.unitPrice)\n      return this.form.name.trim() !== '' && cents !== null && cents >= 0\n    },\n    filteredItems() {\n      const query = this.query.trim().toLowerCase()\n      if (!query) {\n        return this.items\n      }\n      return this.items.filter((item) => {\n        const haystack = [item.name, item.description]\n          .filter(Boolean)\n          .join(' ')\n          .toLowerCase()\n        return haystack.includes(query)\n      })\n    },\n  },\n  async mounted() {\n    await this.load()\n  },\n  methods: {\n    t(key) {\n      return this.$tKey(`products.${key}`, key)\n    },\n    async load() {\n      this.loading = true\n      this.error = ''\n      try {\n        const data = await getProducts()\n        this.items = Array.isArray(data) ? data : []\n      } catch (e) {\n        this.error = this.t('loadError')\n      } finally {\n        this.loading = false\n      }\n    },\n    resetForm() {\n      this.editingId = null\n      this.form = {\n        name: '',\n        description: '',\n        unitPrice: '',\n      }\n      this.fieldErrors = {}\n      this.error = ''\n    },\n    openCreateModal() {\n      this.resetForm()\n      this.showModal = true\n    },\n    closeModal() {\n      this.showModal = false\n      this.resetForm()\n    },\n    editItem(item) {\n      this.editingId = item.id\n      this.form = {\n        name: item.name,\n        description: item.description || '',\n        unitPrice: inputFromCents(item.unitPriceCents),\n      }\n      this.fieldErrors = {}\n      this.error = ''\n      this.showModal = true\n    },\n    clearFieldErrors() {\n      this.fieldErrors = {}\n    },\n    async save() {\n      this.clearFieldErrors()\n      if (!this.canSave) {\n        const errors = {}\n        if (!this.form.name.trim()) {\n          errors.name = this.t('nameError')\n        }\n        if (centsFromInput(this.form.unitPrice) === null) {\n          errors.unitPrice = this.t('unitPriceError')\n        }\n        this.fieldErrors = errors\n        return\n      }\n\n      const cents = centsFromInput(this.form.unitPrice)\n      if (cents === null || cents < 0) {\n        this.fieldErrors = { unitPrice: this.t('unitPriceMinError') }\n        return\n      }\n\n      this.saving = true\n      this.saved = false\n      this.error = ''\n\n      const payload = {\n        name: this.form.name.trim(),\n        description: this.form.description.trim(),\n        unitPriceCents: cents,\n      }\n\n      try {\n        if (this.editingId) {\n          const saved = await updateProduct(this.editingId, payload)\n          this.items = this.items.map((item) =>\n            item.id === this.editingId ? saved : item\n          )\n        } else {\n          const saved = await createProduct(payload)\n          this.items = [...this.items, saved]\n          this.resetForm()\n        }\n\n        this.saved = true\n        window.setTimeout(() => {\n          this.saved = false\n        }, 2000)\n        this.closeModal()\n      } catch (e) {\n        this.error = this.t('saveError')\n      } finally {\n        this.saving = false\n      }\n    },\n    async removeItem(item) {\n      if (!window.confirm(this.t('deleteConfirm'))) {\n        return\n      }\n      this.saving = true\n      this.error = ''\n      try {\n        await deleteProduct(item.id)\n        this.items = this.items.filter((entry) => entry.id !== item.id)\n        if (this.editingId === item.id) {\n          this.resetForm()\n        }\n        if (this.showModal) {\n          this.closeModal()\n        }\n      } catch (e) {\n        this.error = this.t('deleteError')\n      } finally {\n        this.saving = false\n      }\n    },\n    formatPrice(value) {\n      return this.$formatCurrencyCents(value)\n    },\n  },\n}\n</script>\n\n<style scoped>\n.products {\n  display: flex;\n  flex-direction: column;\n  gap: 24px;\n}\n\n.header {\n  display: flex;\n  align-items: flex-end;\n  justify-content: space-between;\n  gap: 16px;\n}\n\n.subline {\n  margin: 4px 0 0;\n  color: var(--color-text-lighter, #6b7280);\n}\n\n.filters {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 12px 16px;\n  align-items: flex-end;\n  background: var(--color-background-dark, #f3f4f6);\n  border: 1px solid var(--color-border, #e5e7eb);\n  border-radius: 10px;\n  padding: 12px;\n}\n\n.filter-group {\n  min-width: 200px;\n  flex: 1 1 220px;\n}\n\n.table {\n  width: 100%;\n  border-collapse: collapse;\n}\n\n.table th,\n.table td {\n  padding: 10px 8px;\n  border-bottom: 1px solid var(--color-border, #e5e7eb);\n  vertical-align: top;\n}\n\n.table th.price,\n.table td.price {\n  text-align: right;\n  white-space: nowrap;\n}\n\n.table th.actions,\n.table td.actions {\n  text-align: right;\n  white-space: nowrap;\n}\n\n.table td.actions > * {\n  margin-left: 8px;\n}\n\n.table td.name {\n  font-weight: 600;\n}\n\n.actions {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  flex-wrap: wrap;\n}\n\n.hint {\n  color: var(--color-text-lighter, #6b7280);\n}\n\n.success {\n  color: var(--color-success, #2d9a4f);\n}\n\n.error {\n  color: var(--color-error, #b91c1c);\n}\n\n.field-error {\n  color: var(--color-error, #b91c1c);\n  font-size: 12px;\n}\n\n.modal__content {\n  margin: calc(var(--default-grid-baseline) * 4);\n  display: flex;\n  flex-direction: column;\n  gap: 12px;\n}\n\n.form-group {\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n  margin: calc(var(--default-grid-baseline) * 2) 0;\n}\n\n@media (max-width: 900px) {\n  .header {\n    flex-directio